"""Unit 57: Tagalog Basic Course, Semester II, Chapter 24, Lesson 2: General Manners and Etiquette.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (piloting edition, September 2017).
Pictures, audio, grid matrices, partner work and role plays are left out; the book's answer keys are used (misprints noted).
Numbers in spoken lines are written in words."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def P(rows):
    return [(t, e) for _, t, e in rows]


