        + [F("Makiplantsa ___ ng damit ko. (please)", "nga", ["ang", "kay"], "nga."), F("Pakikuha nga ang aking ___. (backpack)", "backpack", ["mansanas", "plato"], "backpack."), F("Pakidala ang mga mansanas kay ___. (Dolores)", "Dolores", ["Kuya", "Ate"], "Dolores."), F("Hindi ___. Male-late na ako sa klase. (possible)", "puwede", ["bisi", "oo"], "puwede.")]
